test('invoiceTotals with tier-based discounts', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // Uses tier discount: 5%
    ],
  });

  const totals = invoiceTotals(result.value);
  // Line total: 5 * 8500 = 42500
  // Discount: 42500 * 5 / 100 = 2125
  // Amount after discount: 42500 - 2125 = 40375
  // VAT: 40375 * 21 / 100 = 8478.75 ≈ 8479
  // Total: 40375 + 8479 = 48854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals calculates VAT with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer A4', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 100 * 37 = 3700, VAT = 3700 * 9 / 100 = 333
  // Line 2: 1 * 60000 = 60000, VAT = 60000 * 0 / 100 = 0
  // Subtotal: 63700
  // Total VAT: 333
  // Total: 63700 + 333 = 64033
  assert.equal(totals.subtotal, 63700);
  assert.equal(totals.vat, 333);
  assert.equal(totals.total, 64033);
});

