  // Total VAT: 16513
  // Total: 89980 - 8500 + 16513 = 97993
  assert.equal(totals.subtotal, 89980);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 16513);
  assert.equal(totals.total, 97993);
});

